from solution import decimal_to_binary


def test_issue_example_eight():
    """Example: decimal_to_binary(8) == '1000'."""
    assert decimal_to_binary(8) == '1000'  # 8 = 1*8 + 0*4 + 0*2 + 0*1


def test_issue_zero():
    """Convert decimal number 0 to its binary equivalent '0'."""
    assert decimal_to_binary(0) == '0'  # 0 = 0*1


def test_issue_one():
    """Convert decimal number 1 to its binary equivalent '1'."""
    assert decimal_to_binary(1) == '1'  # 1 = 1*1


def test_issue_two():
    """Convert decimal number 2 to its binary equivalent '10'."""
    assert decimal_to_binary(2) == '10'  # 2 = 1*2 + 0*1


def test_issue_five():
    """Convert decimal number 5 to its binary equivalent '101'."""
    assert decimal_to_binary(5) == '101'  # 5 = 4+1 = 1*4 + 0*2 + 1*1


def test_issue_ten():
    """Convert decimal number 10 to its binary equivalent '1010'."""
    assert decimal_to_binary(10) == '1010'  # 10 = 8+2 = 1*8 + 0*4 + 1*2 + 0*1


def test_issue_fifteen_all_ones():
    """Convert decimal number 15 to its binary equivalent '1111'."""
    assert decimal_to_binary(15) == '1111'  # 15 = 8+4+2+1 = 1*8+1*4+1*2+1*1


def test_issue_sixteen_power_of_two():
    """Convert decimal number 16 to its binary equivalent '10000'."""
    assert decimal_to_binary(16) == '10000'  # 16 = 1*16 + 0*8 + 0*4 + 0*2 + 0*1


def test_issue_large_255():
    """Convert decimal number 255 to its binary equivalent '11111111'."""
    assert decimal_to_binary(255) == '11111111'  # 255 = 128+64+32+16+8+4+2+1


def test_contract_returns_str():
    """Binary equivalent must be returned as a string."""
    result = decimal_to_binary(6)  # 6 = 4+2 = 1*4 + 1*2 + 0*1 -> '110'
    assert isinstance(result, str)


def test_contract_only_zero_one_chars():
    """Binary equivalent must contain only '0' and '1' characters."""
    result = decimal_to_binary(13)  # 13 = 8+4+1 -> '1101'
    assert set(result) <= {'0', '1'}


def test_contract_roundtrip_value():
    """Binary equivalent must satisfy int(result, 2) == n."""
    n = 13  # 13 = 8+4+1 -> '1101', int('1101', 2) = 13
    assert int(decimal_to_binary(n), 2) == n
